@push('scripts')<script>(()=>{function init(){if(!window.jQuery||!window.jQuery.fn.select2){setTimeout(init,50);return;}const $=window.jQuery,base=@json(url('academic/withdrawal-requests'));$('.select2').select2({theme:'bootstrap-5',width:'100%',dir:document.documentElement.dir==='rtl'?'rtl':'ltr'});$('.js-flatpickr-date').each(function(){if(window.flatpickr&&!this._flatpickr)flatpickr(this,{dateFormat:'Y-m-d',allowInput:true,disableMobile:true});});function loadStudents(){const institution=$('#institution_id').val(),branch=$('#branch_id').val(),student=$('#academic_student_id');student.empty().append(new Option(@json(__('Select Student')),''));if(!institution)return;$.get(base+'/students',{institution_id:institution,branch_id:branch},rows=>{rows.forEach(r=>student.append(new Option(r.name,r.id,false,false).attr('data-civil',r.civil_id||'').attr('data-class',r.class_name||'').attr('data-guardian',r.guardian_name||'')));student.trigger('change');});}$('#institution_id').on('change',function(){const branch=$('#branch_id');branch.empty().append(new Option(@json(__('Select Branch')),''));$.get(base+'/branches/'+this.value,rows=>{rows.forEach(r=>branch.append(new Option(r.name,r.id)));branch.trigger('change');loadStudents();});});$('#branch_id').on('change',loadStudents);$('#academic_student_id').on('change',function(){const option=$(this).find(':selected');$('#student_civil_id').val(option.data('civil')||'');$('#student_class').val(option.data('class')||'');$('#guardian_name').val(option.data('guardian')||'');});function signature(canvasId,inputId){const canvas=document.getElementById(canvasId),ctx=canvas.getContext('2d'),input=document.getElementById(inputId);let drawing=false;const resize=()=>{const rect=canvas.getBoundingClientRect();canvas.width=rect.width;canvas.height=160;const current=input.value;if(current){const image=new Image();image.onload=()=>ctx.drawImage(image,0,0,canvas.width,canvas.height);image.src=current;}};resize();window.addEventListener('resize',resize);canvas.addEventListener('pointerdown',e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(e.offsetX,e.offsetY);});canvas.addEventListener('pointermove',e=>{if(!drawing)return;ctx.lineWidth=2;ctx.lineCap='round';ctx.lineTo(e.offsetX,e.offsetY);ctx.stroke();input.value=canvas.toDataURL('image/png');});canvas.addEventListener('pointerup',()=>drawing=false);}signature('parent_canvas','parent_signature');signature('manager_canvas','branch_manager_signature');$('.clear-signature').on('click',function(){const canvas=document.getElementById($(this).data('canvas'));canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);$('#'+$(this).data('input')).val('');});$('#academic_student_id').trigger('change');}init();})();</script>@endpush
